40	app.Services.GetRequiredService<ILlmClient>();
41	app.Services.GetRequiredService<Precios>();
42	
43	app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));
44	
45	app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente,
46	    Auditoria auditoria, Precios precios, ILogger<Program> log) =>
47	{
48	    // Un solo punto de registro: el finally cubre toda ruta de salida.
49	    string? rolAud = null, idAud = null, preguntaAud = null;
50	    var codigo = 500;
51	    IReadOnlyList<Cita> citasAud = [];
52	    var medicion = new MedicionUso();
53	
54	    IResult Error(int c, string msg)
55	    {
56	        codigo = c;
57	        return Results.Json(new { error = msg }, statusCode: c);
58	    }
59	
60	    try
61	    {
62	        const int MaxCuerpo = 64 * 1024;
63	        var limite = req.HttpContext.Features.Get<Microsoft.AspNetCore.Http.Features.IHttpMaxRequestBodySizeFeature>();
64	        if (limite is { IsReadOnly: false }) limite.MaxRequestBodySize = MaxCuerpo;
65	
66	        JsonDocument doc;
67	        try
68	        {
69	            using var ms = new MemoryStream();
70	            var buf = new byte[8192];
71	            int n;
72	            while ((n = await req.Body.ReadAsync(buf, req.HttpContext.RequestAborted)) > 0)
73	            {
74	                if (ms.Length + n > MaxCuerpo) return Error(400, "El cuerpo es demasiado grande.");
75	                ms.Write(buf, 0, n);
76	            }
77	            ms.Position = 0;
78	            doc = await JsonDocument.ParseAsync(ms);
79	        }
80	        catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
81	        catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
82	        catch (Exception) { return Error(400, "No se pudo leer el cuerpo de la petición."); }
83	
84	        using (doc)
85	        {
86	            var raiz = doc.RootElement;
87	            if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
88	
89	            static string? Texto(JsonElement e, string nombre) =>
90	                e.ValueKind == JsonValueKind.Object && e.TryGetProperty(nombre, out var v) && v.ValueKind == JsonValueKind.String
91	                    ? v.GetString() : null;
92	            try
93	            {
94	                preguntaAud = Texto(raiz, "pregunta");
95	                if (raiz.TryGetProperty("usuario", out var uAud))
96	                {
97	                    rolAud = Texto(uAud, "rol");
98	                    idAud = Texto(uAud, "id");
99	                }
100	            }
101	            catch (Exception e) when (e is InvalidOperationException or FormatException)
102	            {
103	                // Bytes que no son UTF-8 válido dentro de una cadena JSON: ParseAsync no falla, GetString sí.
104	                preguntaAud = rolAud = idAud = null;
105	                return Error(400, "El cuerpo no es un JSON válido.");
106	            }
107	
108	            if (string.IsNullOrWhiteSpace(preguntaAud)) return Error(400, "La pregunta es obligatoria.");
109	            if (preguntaAud.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
110	
111	            if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
112	                return Error(400, "El usuario es obligatorio.");
113	            if (rolAud == null) return Error(400, "El rol es obligatorio.");
114	            if (rolAud != "estudiante" && rolAud != "coordinador")
115	                return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
116	            if (string.IsNullOrWhiteSpace(idAud)) return Error(400, "El id del usuario es obligatorio.");
117	
118	            var usuario = Permisos.ResolverUsuario(datos, rolAud, idAud);
119	            if (usuario == null) return Error(403, "Usuario no válido.");
120	            if (Permisos.MencionaTercero(datos, usuario, preguntaAud))
121	                return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");
122	
123	            if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
124	                return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");
125	
126	            var plazo = double.TryParse(cfg["Asistente:PlazoSegundos"], System.Globalization.NumberStyles.Float,
127	                System.Globalization.CultureInfo.InvariantCulture, out var seg) && seg > 0 ? seg : 90;
128	            using var cts = CancellationTokenSource.CreateLinkedTokenSource(req.HttpContext.RequestAborted);
129	            cts.CancelAfter(TimeSpan.FromSeconds(plazo));
130	
131	            AsistenteResultado res;
132	            try { res = await asistente.ResponderAsync(usuario, preguntaAud, cts.Token, medicion); }
133	            catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
134	            catch (Exception e)
135	            {
136	                log.LogWarning("Falla del asistente o del proveedor ({Tipo}).", e.GetType().Name);
137	                return Error(503, "El proveedor del modelo no está disponible.");
138	            }
139	
140	            if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");
141	
142	            codigo = 200;
143	            citasAud = res.Citas;
144	            return Results.Json(new
145	            {
146	                respuesta = res.Respuesta,
147	                citas = res.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }),
148	                usoDatosEstudiante = res.UsoDatosEstudiante,
149	                tokens = medicion.Total,
150	                costoUsd = precios.Costo(medicion.TokensEntrada, medicion.TokensSalida),
151	            });
152	        }
153	    }
