120	            if (Permisos.MencionaTercero(datos, usuario, preguntaAud))
121	                return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");
122	
123	            if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
124	                return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");
125	
126	            var plazo = double.TryParse(cfg["Asistente:PlazoSegundos"], System.Globalization.NumberStyles.Float,
127	                System.Globalization.CultureInfo.InvariantCulture, out var seg) && seg > 0 ? seg : 90;
128	            using var cts = CancellationTokenSource.CreateLinkedTokenSource(req.HttpContext.RequestAborted);
129	            cts.CancelAfter(TimeSpan.FromSeconds(plazo));
130	
131	            AsistenteResultado res;
132	            try { res = await asistente.ResponderAsync(usuario, preguntaAud, cts.Token, medicion); }
133	            catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
134	            catch (Exception e)
135	            {
136	                log.LogWarning("Falla del asistente o del proveedor ({Tipo}).", e.GetType().Name);
137	                return Error(503, "El proveedor del modelo no está disponible.");
138	            }
139	
140	            if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");
141	
142	            codigo = 200;
143	            citasAud = res.Citas;
144	            return Results.Json(new
145	            {
146	                respuesta = res.Respuesta,
147	                citas = res.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }),
148	                usoDatosEstudiante = res.UsoDatosEstudiante,
149	                tokens = medicion.Total,
150	                costoUsd = precios.Costo(medicion.TokensEntrada, medicion.TokensSalida),
151	            });
152	        }
153	    }
154	    catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested)
155	    {
156	        codigo = 499;
157	        throw;
158	    }
159	    catch (Exception e)
160	    {
161	        log.LogError("Excepción inesperada ({Tipo}).", e.GetType().Name);
162	        return Error(503, "El servicio no está disponible.");
163	    }
