286	    // El runner toma la raíz subiendo desde el directorio de trabajo hasta un TutorFlow.sln: se fabrica una raíz temporal.
287	
288	    string RaizTemporal()
289	    {
290	        var raiz = NuevoDir();
291	        File.WriteAllText(Path.Combine(raiz, "TutorFlow.sln"), "");
292	        return raiz;
293	    }
294	
295	    static string RutaRaiz(string raiz) => Path.Combine(raiz, "logs", "auditoria.jsonl");
296	    static string RutaSrc(string raiz) => Path.Combine(raiz, "src", "TutorFlow.Api", "logs", "auditoria.jsonl");
297	
298	    static void Sembrar(string ruta, DateTime ultimaEscritura)
299	    {
300	        Directory.CreateDirectory(Path.GetDirectoryName(ruta)!);
301	        // Una línea previa que no coincide con ninguna pregunta del eval.
302	        File.WriteAllText(ruta, "{\"pregunta\":\"previa\",\"id\":\"X\",\"codigo\":200,\"tokens\":1}\n");
303	        File.SetLastWriteTimeUtc(ruta, ultimaEscritura);
304	    }
305	
306	    async Task<Salida> CorreEnRaiz(string raiz, string rutaQueEscribeLaApi)
307	    {
308	        var data = NuevoDir();
309	        Directory.CreateDirectory(Path.Combine(data, "reglamento"));
310	        Directory.CreateDirectory(Path.Combine(data, "api"));
311	        File.WriteAllText(Path.Combine(data, "reglamento", Doc), "# T\n\n## Plazos\n\ntexto\n");
312	        File.WriteAllText(Path.Combine(data, "api", "estudiantes.json"), Estudiantes);
313	        File.WriteAllText(Path.Combine(data, "api", "coordinadores.json"), Coordinadores);
314	        File.WriteAllText(Path.Combine(data, "preguntas-ejemplo.json"), "[" + Caso("E-A", "pregunta-a") + "]");
315	        using var api = new ApiFalsa(Guion, rutaQueEscribeLaApi);
316	        var s = await Ejecutar(data, raiz, api.Url, null);
317	        // El runner escribió su resultado en <raíz>/evals, no en el repositorio.
318	        Assert.True(File.Exists(Path.Combine(raiz, "evals", "resultados", "ultimo.json")));
319	        return s;
320	    }
